import{_ as t,o as s,c as a,a0 as o}from"./chunks/framework.DVUHX04-.js";const u=JSON.parse('{"title":"/ctx flags guidelines that duplicate tool descriptions","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0022-ctx-flags-guidelines-that-duplicate-tool-descriptions.md","filePath":"adr/0022-ctx-flags-guidelines-that-duplicate-tool-descriptions.md","lastUpdated":1789777524000}'),i={name:"adr/0022-ctx-flags-guidelines-that-duplicate-tool-descriptions.md"};function n(l,e,r,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="ctx-flags-guidelines-that-duplicate-tool-descriptions" tabindex="-1">/ctx flags guidelines that duplicate tool descriptions <a class="header-anchor" href="#ctx-flags-guidelines-that-duplicate-tool-descriptions" aria-label="Permalink to &quot;/ctx flags guidelines that duplicate tool descriptions&quot;">​</a></h1><p>A tool&#39;s JSON description is resent on every LLM call as part of the tool entry. A Prompt guideline that merely restates that description adds cost without adding information, and a reader of the /ctx report has no way to see the overlap.</p><p>After the session has at least one provider request, a guideline row whose text largely restates a sent tool description shows a <code>duplicates tool description</code> note, in both the text table and the TUI. Before the first provider request, rows show with no flag. The comparison runs against the tool descriptions from the last captured provider request</p><ul><li>the text actually sent - never against a rebuilt schema.</li></ul><p>Detection rule: normalize both sides (lowercase, punctuation stripped, spaces collapsed) and flag when the longest common substring between the guideline and any captured tool description is at least 80 percent of the guideline&#39;s normalized length and at least 24 characters. The threshold is deliberately conservative: it catches the verbatim and prefixed-verbatim shapes, misses paraphrases in v1, and avoids false positives that would train the reader to ignore the flag.</p><p>Prompt snippets are never flagged: a one-line restatement of the tool is the design of the available-tools section, so flagging them means flagging nearly all of them.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>No flag.</strong> The cost is visible in the numbers, but the overlap is not.</li><li><strong>Semantic or embedding similarity.</strong> Catches paraphrases, but needs a model call or a bundled model in a pure, offline core, and the result moves with the model.</li><li><strong>Keyword overlap.</strong> Cheap, but false positives on common words.</li><li><strong>Conservative longest-common-substring (chosen).</strong> Pure text, deterministic, and the miss profile is known: paraphrases.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The flag appears only after the first call; a session at zero calls shows the same rows without the note.</li><li>A guideline that adds trigger conditions (when to use the tool) around a short quote of the description stays unflagged, because the shared part falls under the 80 percent share.</li><li>The note rides the row&#39;s existing <code>note</code> field, so the text table and the TUI pick it up from the same place; the TUI clips long guideline labels to keep the note whole.</li><li>The rule&#39;s constants (80 percent share, 24-character floor) are the seam for loosening detection in a later version.</li></ul>',10)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
